class Solution {
    public int computeArea(int ax1,int ay1,int ax2,int ay2,int bx1,int by1,int bx2,int by2){
        long first=(long)(ax2-ax1)*(ay2-ay1),second=(long)(bx2-bx1)*(by2-by1);
        long width=Math.max(0,Math.min(ax2,bx2)-Math.max(ax1,bx1));
        long height=Math.max(0,Math.min(ay2,by2)-Math.max(ay1,by1));
        return(int)(first+second-width*height);
    }
}

code.kotlin:
class Solution {
    fun computeArea(ax1:Int,ay1:Int,ax2:Int,ay2:Int,bx1:Int,by1:Int,bx2:Int,by2:Int):Int{
        val first=(ax2-ax1).toLong()*(ay2-ay1);
        val second=(bx2-bx1).toLong()*(by2-by1);
        val width=maxOf(0,minOf(ax2,bx2)-maxOf(ax1,bx1));
        val height=maxOf(0,minOf(ay2,by2)-maxOf(ay1,by1));
        return(first+second-width.toLong()*height).toInt()
    }
}

